const src = $json || {};
const exec = src.execution || {};
const workflow = src.workflow || {};
const lastNode = src.lastNodeExecuted || src.node?.name || '';
const err = src.error || {};
const msg = err.message || src.message || 'Unknown workflow error';
const stack = err.stack || '';
function pick(obj, path, fallback='') {
  try { return path.reduce((a,k)=>a&&a[k]!==undefined?a[k]:undefined, obj) ?? fallback; } catch { return fallback; }
}
const ingestion_id = pick(exec, ['data','resultData','runData','Normalize Input',0,'data','main',0,0,'json','ingestion_id'], '') || pick(exec, ['data','resultData','runData','Create Ingestion Context',0,'data','main',0,0,'json','ingestion_id'], '');
return [{ json: {
  ingestion_id,
  execution_id: src.execution?.id || src.executionId || '',
  workflow_id: workflow.id || '',
  workflow_name: workflow.name || '',
  failed_node: lastNode,
  error_message: msg,
  error_stack: stack,
  timestamp: new Date().toISOString(),
  input_excerpt: '',
  raw_error_json: JSON.stringify(src).slice(0, 20000)
}}];

const fs = require('fs');
const path = require('path');
const item = $json || {};
const outPath = process.env.SIGA_ERROR_LOG_PATH || '/data/.openclaw/workspace/archive/siga_workflow_error_log.jsonl';
fs.mkdirSync(path.dirname(outPath), { recursive: true });
fs.appendFileSync(outPath, JSON.stringify(item) + '\n', 'utf8');
return [{ json: { ...item, error_log_path: outPath, logged: true } }];
